<?php require 'inc/bootstrap.php';need();$u=me();$mgr=$u['role']!=='teacher';
$p=$_GET['p']??'t'.currentTerm();if(!in_array($p,['week','t1','t2','t3','year']))$p='t'.currentTerm();
[$from,$to,$label]=period($p);$f=['from'=>$from,'to'=>$to];if(!$mgr)$f['uid']=$u['id'];$rows=reports($f);
$ty=$sk=$cl=$mo=$te=[];$pt=$bo=$gi=0;$st=['submitted'=>0,'reviewed'=>0,'rejected'=>0];
foreach($rows as $r){$ty[$r['type']]=($ty[$r['type']]??0)+1;foreach(array_filter(explode(',',$r['skills'])) as $s)$sk[$s]=($sk[$s]??0)+1;$c=$r['class_name']?:'(no class)';$cl[$c]=($cl[$c]??0)+1;
 $m=substr($r['activity_date'],0,7);$mo[$m]=($mo[$m]??0)+1;$te[$r['teacher']]=($te[$r['teacher']]??0)+1;$pt+=$r['participants'];$bo+=$r['boys'];$gi+=$r['girls'];$st[$r['status']]=($st[$r['status']]??0)+1;}
ksort($mo);top('Dashboard');?>
<h1>Dashboard <span class="mu">- <?=h($label)?> (<?=$from?> to <?=$to?>)</span></h1>
<div class="row np" style="margin:0 0 12px"><?php foreach(['week'=>'This week','t1'=>'Term 1','t2'=>'Term 2','t3'=>'Term 3','year'=>'Annual'] as $k=>$v)echo '<a class="btn '.($p===$k?'on':'s').'" href="?p='.$k.'">'.$v.'</a>';?></div>
<div class="card st"><div><b><?=count($rows)?></b>activities</div><div><b><?=$pt?></b>participations</div><div><b><?=$gi?> / <?=$bo?></b>girls / boys</div><div><b><?=count($te)?></b>teachers reporting</div><div><b><?=$st['submitted']?></b>pending review</div><div><b><?=$st['reviewed']?></b>approved</div><div><b><?=$st['rejected']?></b>rejected</div></div>
<?php $bk='dashboard.php?p='.$p;if($mgr){$pend=array_values(array_filter($rows,fn($r)=>$r['status']==='submitted'&&$r['user_id']!=$u['id']));if($pend){?><div class="card"><h2>Awaiting your review (<?=count($pend)?>)</h2><?php rtable(array_slice($pend,0,10),$bk);if(count($pend)>10)echo '<p class="mu">Showing 10. <a href="reports.php?status=submitted">See all pending reports</a></p>';?></div><?php }}
else{$rej=array_values(array_filter($rows,fn($r)=>$r['status']==='rejected'));if($rej){?><div class="card"><h2>Rejected - please correct and resubmit (<?=count($rej)?>)</h2><?php foreach($rej as $r)echo '<p><a href="report_view.php?id='.$r['id'].'">'.h($r['activity_date'].' - '.$r['type']).'</a><br><span class="mu">'.h($r['feedback']).'</span></p>';?></div><?php }}?>
<?php $mc=myClasses($u['id']);if(!$mgr||$mc){?><div class="card sc"><h2>My classes</h2><?php if(!$mc)echo '<p class="mu">No class has been assigned to you yet. The CPD Coordinator assigns classes to teachers.</p>';else{echo '<table><tr><th>Class</th><th>Subject</th><th>Students</th><th>Reports in this period</th><th></th></tr>';foreach($mc as $c){$n=count(array_filter($rows,fn($r)=>$r['class_id']==$c['id']&&$r['user_id']==$u['id']));echo '<tr><td><b>'.h($c['name']).'</b></td><td>'.h($c['subj']?:'-').'</td><td>'.($c['boys']+$c['girls']?:'-').'</td><td>'.($n?:'<span class="tag warn">none yet</span>').'</td><td><a class="btn sm" href="report_form.php?cid='.$c['id'].'">+ Report</a></td></tr>';}echo '</table>';}?></div><?php }?>
<?php if($mgr):$miss=missing($from,$to);$mcl=missingClasses($from,$to);?><div class="card np"><h2>Generate report</h2><form method="get" action="export.php"><input type="hidden" name="p" value="<?=h($p)?>"><div class="g">
<div><label>Teacher</label><select name="uid"><option value="">All teachers</option><?php foreach(q("SELECT id,name FROM users WHERE role IN('teacher','cpd') ORDER BY name") as $x)echo "<option value=\"{$x['id']}\">".h($x['name']).'</option>';?></select></div>
<div><label>Class</label><input name="cls" list="cl" placeholder="All classes"><datalist id="cl"><?php foreach(classNames() as $x)echo '<option value="'.h($x).'">';?></datalist></div></div>
<p class="mu">Period: <?=h($label)?>. Change it with the buttons above. For custom dates use the Reports page and its Export buttons.</p>
<button name="fmt" value="pdf">Download PDF</button> <button class="s" name="fmt" value="csv">Export CSV (Excel)</button></form></div>
<div class="card"><h2>Teachers with no report in this period (<?=count($miss)?>)</h2><?=$miss?h(implode(', ',$miss)):'<span class="ok" style="display:inline-block;margin:0">Every active teacher has reported.</span>'?></div>
<div class="card"><h2>Classes with no report in this period (<?=count($mcl)?>)</h2><?=$mcl?h(implode(', ',$mcl)):'<span class="ok" style="display:inline-block;margin:0">Every active class has at least one report, or no classes are registered yet.</span>'?><?php if($u['role']==='cpd')echo '<p class="mu"><a href="classes.php">Manage classes</a></p>';?></div><?php endif;?>
<div class="g2"><div class="card"><h2>Activities by type</h2><?php hb($ty);?></div><div class="card"><h2>Language skills practised</h2><?php hb($sk);?></div>
<div class="card"><h2>Activities per month</h2><?php hb($mo,false);?></div><div class="card"><h2>Activities by class</h2><?php hb($cl);?></div></div>
<?php if($mgr&&$te):?><div class="card"><h2>Reports per teacher</h2><?php hb($te);?></div><?php endif;?>
<div class="card sc"><h2>Recent reports</h2><table><?php foreach(array_slice($rows,0,8) as $r)echo '<tr><td>'.h($r['activity_date']).'</td><td><a href="report_view.php?id='.$r['id'].'">'.h($r['type']).'</a></td><td>'.h($r['teacher']).'</td><td>'.h($r['class_name']).'</td><td>'.stag($r['status']).'</td></tr>';
if(!$rows)echo '<tr><td class="mu">No activities recorded in this period yet.</td></tr>';?></table></div><?php bot();
